export const glossary = [
  { term: 'sfc', definition: 'System File Checker — Windows utility that scans for and repairs system file corruption.' },
  { term: 'DISM', definition: 'Deployment Image Servicing and Management — Windows tool for repairing the component store and servicing images.' },
  { term: 'APIPA', definition: 'Automatic Private IP Addressing — 169.254.0.0/16 self-assigned when DHCP fails.' },
  { term: 'CMDB', definition: 'Configuration Management Database — inventory of IT assets and their relationships.' },
];

